import React,{useEffect,useRef,useState} from 'react';
import {pages,modules,resources,sections,moduleSections,faq,sourceLinks} from './content.js';
import {Badge,Icon,Exhibit,Diff,Arithmetic,Donut,Bridge,EventMatrix,Timeline,Correspondence} from './Visuals.jsx';
