export function track(name,context={}){if(typeof window==='undefined')return;const valid=['landing_view','buyer_qualified','offer_12_selected','demo_open','evidence_view','override_view','price_view','pilot_request','consent_submit'];if(!valid.includes(name))return;const q=new URLSearchParams(window.location.search);const safe={};['offer_id','path','role','intent'].forEach(k=>{if(context[k])safe[k]=String(context[k]).slice(0,80)});const e={name,...safe,utm_source:(q.get('utm_source')||'').slice(0,80),utm_campaign:(q.get('utm_campaign')||'').slice(0,80),time:new Date().toISOString()};window.__earnedlineEvents=(window.__earnedlineEvents||[]).concat(e).slice(-100);}
export function Btn({href,children,kind='primary',flip=false,className='',onClick,...rest}){const C=href?'a':'button';return <C href={href} className={'btn btn-'+kind+(flip?' flip-label':'')+' '+className} onClick={onClick} {...rest}>{kind==='primary'&&<span className="button-shutters" aria-hidden="true">{[0,1,2,3].map(n=><i key={n}/>)}</span>}<span className="btn-label">{children}</span><Icon name={kind==='text'?'arrow-up-right':'arrow-right'}/></C>}
export function Reveal({children,className='',as:Tag='div',motion='reveal',...props}){const ref=useRef(null);useEffect(()=>{if(!ref.current)return;const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in-view');io.unobserve(e.target)}}),{threshold:.1});io.observe(ref.current);return()=>io.disconnect()},[]);return <Tag ref={ref} className={className+' reveal'} data-motion={motion} {...props}>{children}</Tag>}
function Header({route}){const [menu,setMenu]=useState(null),[mobile,setMobile]=useState(false);const nav=useRef(null),mobilePanel=useRef(null),menuBtn=useRef(null);useEffect(()=>{const close=e=>{if(e.key==='Escape'){setMenu(null);setMobile(false);menuBtn.current?.focus()}};const outside=e=>{if(nav.current&&!nav.current.contains(e.target))setMenu(null)};document.addEventListener('keydown',close);document.addEventListener('pointerdown',outside);return()=>{document.removeEventListener('keydown',close);document.removeEventListener('pointerdown',outside)}},[]);useEffect(()=>{if(!mobile)return;const old=document.body.style.overflow;document.body.style.overflow='hidden';mobilePanel.current?.querySelector('a')?.focus();const trap=e=>{if(e.key!=='Tab')return;const els=[menuBtn.current,...mobilePanel.current.querySelectorAll('a,button')].filter(Boolean);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}};document.addEventListener('keydown',trap);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',trap)}},[mobile]);return <><a className="skip-link" href="#main">Skip to content</a><header className="site-header" ref={nav}><div className="nav-inner"><a className="brand" href="/" aria-label="EarnedLine home"><img src="/brand/logos/earnedline-primary.svg" alt="EarnedLine" width="178" height="36"/></a><nav className="desktop-nav" aria-label="Main navigation"><button aria-expanded={menu==='products'} aria-controls="products-menu" onClick={()=>setMenu(menu==='products'?null:'products')}>Products <Icon name="chevron-down" size={15}/></button><a href="/how-it-works" aria-current={route==='/how-it-works'?'page':undefined}>How it works</a><a href="/why-earnedline">Why EarnedLine</a><a href="/pilot">Pilot</a><button aria-expanded={menu==='resources'} aria-controls="resources-menu" onClick={()=>setMenu(menu==='resources'?null:'resources')}>Resources <Icon name="chevron-down" size={15}/></button></nav><div className="nav-actions"><a href="/sign-in" className="signin-link">Sign in</a><Btn href="/request-pilot" className="nav-cta">Discuss a pilot</Btn></div><button className="menu-toggle" ref={menuBtn} aria-label={mobile?'Close navigation':'Open navigation'} aria-expanded={mobile} aria-controls="mobile-nav" onClick={()=>setMobile(!mobile)}><Icon name={mobile?'x':'menu'} size={24}/></button></div>{menu==='products'&&<div className="mega-menu" id="products-menu"><div className="mega-intro"><span className="eyebrow">Five proposed modules</span><h3>Choose the question.<br/>Follow its evidence.</h3><p>Start with contract reconciliation.<br/>Earn the next scope through validation.</p><a href="/products" className="text-link">Explore the product overview <Icon/></a></div><div className="mega-products">{modules.map(m=><a key={m.id} href={m.route}><span className="menu-icon"><Icon name={m.icon}/></span><span><b>{m.name}</b><small>{m.question}</small></span><Icon name="arrow-up-right" size={16}/></a>)}</div></div>}{menu==='resources'&&<div className="mega-menu resources-menu" id="resources-menu"><div className="mega-intro"><span className="eyebrow">The review library</span><h3>A useful place<br/>to start.</h3><a href="/resources" className="text-link">All resources <Icon/></a></div><div className="mega-products">{resources.map(r=><a key={r.route} href={r.route}><Icon name="file-text"/><span><b>{r.label}</b><small>{r.title}</small></span><Icon name="arrow-up-right" size={16}/></a>)}<a href="/evaluation"><Icon name="chart-pie"/><span><b>Pilot evaluation</b><small>Ground truth, effort and the decision gate.</small></span><Icon name="arrow-up-right" size={16}/></a></div></div>}{mobile&&<nav id="mobile-nav" className="mobile-nav" ref={mobilePanel} aria-label="Mobile navigation"><span className="eyebrow">Products</span>{modules.map(m=><a href={m.route} key={m.id}><Icon name={m.icon}/>{m.name}<Icon name="arrow-up-right"/></a>)}<div className="mobile-nav-grid">{[['Product overview','/products'],['How it works','/how-it-works'],['Why EarnedLine','/why-earnedline'],['Pilot + pricing','/pilot'],['Use cases','/use-cases'],['Controls','/controls'],['Resources','/resources'],['About','/about'],['Contact','/contact'],['Sign in','/sign-in']].map(([t,h])=><a href={h} key={h}>{t}</a>)}</div><div className="row"><Btn href="/demo" kind="secondary">Explore demo</Btn><Btn href="/request-pilot">Discuss a pilot</Btn></div></nav>}</header>{menu&&<div className="menu-backdrop" onClick={()=>setMenu(null)} aria-hidden="true"/>}</>}
function Footer(){const [reduced,setReduced]=useState(false);useEffect(()=>setReduced(matchMedia('(prefers-reduced-motion:reduce)').matches||localStorage.getItem('earnedline-motion')==='true'),[]);return <footer className="site-footer"><div className="container"><div className="footer-top"><div><span className="eyebrow">A clearer record. A human decision.</span><h2>Follow what was earned.</h2></div><Btn href="/request-pilot" kind="light">Discuss a pilot</Btn></div><div className="footer-grid"><div className="footer-brand"><a href="/" aria-label="EarnedLine home"><img src="/brand/logos/earnedline-reverse.svg" alt="EarnedLine" width="180" height="37"/></a><p>A research-stage concept for inspectable contract-to-invoice review.</p><div className="social-links"><span aria-label="LinkedIn company profile not yet available"><img src="/brand/icons/social/linkedin.svg" alt="" width="22" height="22"/>LinkedIn</span><span aria-label="Crunchbase company profile not yet available"><img src="/brand/icons/social/crunchbase-icon.png" alt="" width="22" height="22"/>Crunchbase</span></div><small>Company profile links are not yet available.</small></div><div><h4>Products</h4>{modules.map(m=><a href={m.route} key={m.id}>{m.name}</a>)}<a href="/products">Product overview</a></div><div><h4>Explore</h4>{[['Why EarnedLine','/why-earnedline'],['How it works','/how-it-works'],['Use cases','/use-cases'],['Synthetic demo','/demo'],['Pilot + pricing','/pilot'],['Evaluation','/evaluation'],['Resources','/resources']].map(([t,h])=><a href={h} key={h}>{t}</a>)}</div><div><h4>Company</h4>{[['About','/about'],['Contact','/contact'],['Request a walkthrough','/request-demo'],['Controls + limits','/controls'],['Sign in','/sign-in'],['Privacy','/legal/privacy'],['Terms','/legal/terms']].map(([t,h])=><a href={h} key={h}>{t}</a>)}</div></div><div className="footer-bottom"><span>© 2026 EarnedLine · Concept preview</span><span>All product examples use synthetic data.</span><button aria-pressed={reduced} onClick={()=>{const n=!reduced;setReduced(n);localStorage.setItem('earnedline-motion',String(n));document.documentElement.classList.toggle('motion-reduced',n);window.dispatchEvent(new CustomEvent('earnedline-motion',{detail:n}))}}><Icon name={reduced?'pause':'play'} size={15}/>{reduced?'Motion reduced':'Reduce motion'}</button></div></div></footer>}
export function CrispHero({time,still}){const step=still?5:Math.min(5,Math.floor(time/3));return <div className="crisp-hero" data-step={step}><div className="crisp-heading"><span className="eyebrow">Evidence in motion / Acme Analytics</span><h2>{['Start with the signed agreement.','Read the line that sets the allowance.','Trace the quantity to its source.','Compare what reached the invoice.','Keep the existing credit in view.','Hold the correction for human review.'][step]}</h2><Badge>CONCEPT PREVIEW</Badge></div><div className="crisp-workspace"><aside className="crisp-document"><span className="eyebrow">Executed agreement / CT-22</span><h3>Acme Analytics<br/> Customer agreement</h3><small>Signed 12 Aug 2026 · USD · Fictional</small><hr/><b>2. Usage and fees</b><p>C-22.1<br/>The subscription includes <mark>10,000 events per month.</mark></p><p>C-22.2<br/>Additional events are charged at <mark>$0.04 per additional event.</mark></p><span className="crisp-signature">A. Morgan / fictional signatory</span></aside><div className="crisp-review"><div className="crisp-review-header"><span className="eyebrow">September 2026 / CT-22 → I-88</span><Badge type="warning">HELD</Badge></div><h3>Contract-to-invoice review</h3><div className="crisp-facts">{[['Signed clause','10,000','events included','C-22'],['Metered usage','12,000','source events','USG-SEP22'],['Invoice line','$2,000','base fee only','I-88']].map(([a,b,c,d],i)=><div key={a} className={step===i+1?'current':''}><small>{a} / {d}</small><strong>{b}</strong><span>{c}</span></div>)}</div><div className="crisp-gap"><Icon name="circle-alert"/><div><b>$80 candidate discrepancy</b><span>2,000 additional events × $0.04</span></div><Badge type="warning">NOT VERIFIED</Badge></div><div className={'crisp-credit '+(step>=4?'visible':'')}><Icon name="file-text"/><span><b>$40 existing credit / CR-40</b><small>Applicability pending · net not assessed</small></span></div><div className="crisp-authority"><span className="avatar">MC</span><div><b>Mira Chen · fictional reviewer</b><small>Finance + contract/legal approval required</small></div><Icon name="lock-keyhole"/></div></div></div><div className="crisp-foot"><span>DEMO — SYNTHETIC DATA</span><span>No invoice, message or system write executes.</span></div></div>}
function VideoHero(){const video=useRef(null),ref=useRef(null);const [playing,setPlaying]=useState(false),[still,setStill]=useState(false),[time,setTime]=useState(0),[mobileFilm,setMobileFilm]=useState(false);const chapters=[['Signed contract',0],['Executed clause',3],['Metered usage',6],['Invoice line',9],['Existing credit',12],['Held review',15]];useEffect(()=>{const v=video.current;if(!v)return;const phone=matchMedia('(max-width:600px)');const setPhone=()=>setMobileFilm(phone.matches);setPhone();phone.addEventListener('change',setPhone);const reduced=matchMedia('(prefers-reduced-motion:reduce)');const setPref=()=>{setStill(reduced.matches||document.documentElement.classList.contains('motion-reduced'));if(reduced.matches)v.pause()};setPref();reduced.addEventListener('change',setPref);const custom=e=>{setStill(e.detail);if(e.detail)v.pause()};window.addEventListener('earnedline-motion',custom);const io=new IntersectionObserver(es=>{if(!es[0].isIntersecting){v.pause()}else if(!reduced.matches&&!document.documentElement.classList.contains('motion-reduced'))v.play().catch(()=>{})},{threshold:.2});io.observe(ref.current);const hidden=()=>{if(document.hidden)v.pause()};document.addEventListener('visibilitychange',hidden);return()=>{io.disconnect();phone.removeEventListener('change',setPhone);reduced.removeEventListener('change',setPref);window.removeEventListener('earnedline-motion',custom);document.removeEventListener('visibilitychange',hidden)}},[]);return <div className={'hero-media '+(still?'still':'')} ref={ref}><div className="film-topbar"><span><img className="tiny-mark" src="/brand/logos/earnedline-mark-olive.svg" alt=""/>The evidence review</span><span className="film-top-meta">CT-22 → C-22 → I-88</span><Badge>DEMO · SYNTHETIC DATA</Badge><button className="film-top-control" aria-label={playing?'Pause animation':'Play animation'} onClick={()=>{if(still){setStill(false);video.current.play().catch(()=>{})}else if(playing)video.current.pause();else video.current.play().catch(()=>{})}}><Icon name={playing?'pause':'play'} size={16}/></button></div><div className="film-stage"><video ref={video} src={mobileFilm?'/media/earnedline-hero-mobile.mp4':'/media/earnedline-hero.mp4'} poster={mobileFilm?'/media/earnedline-hero-mobile.png':'/media/earnedline-hero-poster.png'} muted playsInline loop preload="metadata" aria-label="Illustrative contract-to-invoice review, ending at held finance approval" onPlay={()=>setPlaying(true)} onPause={()=>setPlaying(false)} onTimeUpdate={e=>setTime(e.currentTarget.currentTime)} className={still?'visually-hidden-video':''}/>{still&&<picture><source media="(max-width:600px)" srcSet="/media/earnedline-hero-mobile.png"/><img src="/media/earnedline-hero-poster.png" alt="Fictional Acme Analytics review:10,000 included,12,000 metered,80 dollar unverified discrepancy,40 dollar credit pending, no invoice sent." width="1440" height="900"/></picture>}<CrispHero time={time} still={still}/><div className="film-progress" style={{'--progress':(time/18*100)+'%'}}/></div><div className="film-bottom"><div className="film-chapters" aria-label="Video chapters">{chapters.map(([label,t],i)=><button key={label} aria-pressed={!still&&time>=t&&time<t+3} onClick={()=>{setStill(false);video.current.currentTime=t;video.current.pause()}}><span>{String(i+1).padStart(2,'0')}</span>{label}</button>)}</div><div className="film-tools"><button onClick={()=>{if(still){setStill(false);video.current.play().catch(()=>{})}else if(playing)video.current.pause();else video.current.play().catch(()=>{})}} aria-label={playing?'Pause hero video':'Play hero video'}><Icon name={playing?'pause':'play'} size={16}/></button><button onClick={()=>{setStill(false);video.current.currentTime=0;video.current.play().catch(()=>{})}} aria-label="Replay hero video"><Icon name="rotate-ccw" size={16}/></button><button onClick={()=>{video.current.pause();setStill(true)}} aria-label="Show static hero"><Icon name="eye" size={16}/></button><a href="/demo" className="film-open" aria-label="Open the interactive demo"><Icon name="arrow-up-right" size={16}/></a></div></div><details className="film-transcript"><summary>Read the visual walkthrough</summary><p>Acme Analytics contract CT-22, clause C-22 includes 10,000 events and charges $0.04 for additional events. September metered usage is 12,000. Invoice I-88 includes only a fictional $2,000 base fee. The gross $80 candidate is NOT VERIFIED. Existing credit CR-40 is $40; applicability is pending. A reviewer holds the record. No invoice, message or system write occurs. All entities and outcomes are fictional.</p></details></div>}
function SectionHead({eyebrow,title,body}){return <div className="section-heading"><div><span className="eyebrow">{eyebrow}</span><h2>{title}</h2></div>{body&&<p>{body}</p>}</div>}
function NarrativeSection({item,index,context}){return <Reveal as="section" className={'narrative-section '+item.layout+(index%2?' reverse':'')} data-section={`${context}-${index}`} motion={item.visual}><div className="container"><div className="narrative-copy"><span className="eyebrow">{String(index+1).padStart(2,'0')} / {context==='home'?'The review':'In context'}</span><h2>{item.title}</h2><p>{item.body}</p>{item.link&&<Btn href={item.link} kind="text">{item.linkLabel||'Explore the example'}</Btn>}</div><Exhibit kind={item.visual} labels={item.labels} id={`${context}-${index}-${item.visual}`}/></div></Reveal>}
function ModuleMini({id}){return <figure className="module-mobile-visual"><div className="mini-disclosure">DEMO · SYNTHETIC DATA <span>CONCEPT PREVIEW</span></div><div className="mini-module-body">{id==='contract'?<><div className="mini-evidence-triad">{[['C-22','10,000','included events'],['USG-SEP22','12,000','metered events'],['I-88','Absent','overage line']].map(([a,b,c])=><div key={a}><small>{a}</small><b>{b}</b><span>{c}</span></div>)}</div><div className="mini-exception"><b>$80 gross candidate</b><Badge type="warning">NOT VERIFIED</Badge></div><small>CR-40 · $40 existing credit · applicability pending</small></>:id==='usage'?<><div className="mini-event-matrix">{Array.from({length:120},(_,i)=><i className={i>=100?'extra':''} key={i}/>)}</div><div className="mini-legend"><span>10,000 included</span><span>2,000 additional</span></div><small>Each cell = 100 metered events. Completeness, exclusions and duplicates still require review.</small></>:id==='renewals'?<><div className="mini-term-track"><span>10% concession</span><span>Renewal review</span></div><div className="mini-legend"><span>1 Jun 2026</span><b>1 Sep 2026</b><span>1 Jun 2027</span></div><div className="mini-exception"><b>Discount still applied</b><Badge type="warning">HELD</Badge></div><small>Harbor Metrics · C-24 / I-89 · check extension amendment</small></>:id==='receivables'?<><div className="mini-message"><div><small>Harbor Ops / I-109</small><b>$450</b><span>Fictional outstanding balance</span></div><div><Icon name="mail"/><b>Draft explanation</b><span>Balance · recipient · wording</span></div></div><div className="mini-exception"><Icon name="lock-keyhole"/><b>Customer dispute open</b><Badge type="warning">NOT SENT</Badge></div><small>No customer message executes. Approval remains separate.</small></>:<><div className="mini-cash-bars"><div><b>$80</b><i/><small>Candidate</small></div><div><b>−$40</b><i/><small>Credit, if applicable</small></div><div><b>$40</b><i/><small>Conditional net</small></div></div><small>CR-40 applicability pending. Billability, invoicing and collected cash: not assessed.</small></>}</div><figcaption>Illustrative evidence. No external action executes.</figcaption></figure>}
function ModuleExplorer({cards=false}){const [active,setActive]=useState('contract'),[scrollMode,setScrollMode]=useState(true),[reduced,setReduced]=useState(false);const stage=useRef(null),frame=useRef(null),tabs=useRef(null);useEffect(()=>{if(cards)return;const media=matchMedia('(prefers-reduced-motion:reduce)');const sync=()=>setReduced(media.matches||document.documentElement.classList.contains('motion-reduced'));sync();media.addEventListener('change',sync);window.addEventListener('earnedline-motion',sync);return()=>{media.removeEventListener('change',sync);window.removeEventListener('earnedline-motion',sync)}},[cards]);useEffect(()=>{if(cards||!scrollMode||reduced)return;let raf=0;const update=()=>{raf=0;if(document.hidden||!stage.current||!frame.current||(frame.current.contains(document.activeElement)&&!document.activeElement.closest('.module-scroll-meta')))return;const rect=stage.current.getBoundingClientRect();const top=parseFloat(getComputedStyle(frame.current).top)||100;const travel=Math.max(1,stage.current.offsetHeight-frame.current.offsetHeight);if(rect.top<innerHeight&&rect.bottom>0){const progress=Math.max(0,Math.min(.999,(-rect.top+top)/travel));setActive(modules[Math.floor(progress*5)].id)}};const schedule=()=>{if(!raf)raf=requestAnimationFrame(update)};window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule);schedule();return()=>{cancelAnimationFrame(raf);window.removeEventListener('scroll',schedule);window.removeEventListener('resize',schedule)}},[cards,scrollMode,reduced]);useEffect(()=>{const row=tabs.current,button=row?.querySelector('[aria-selected="true"]');if(row&&button&&row.scrollWidth>row.clientWidth)row.scrollTo({left:button.offsetLeft-row.offsetLeft-(row.clientWidth-button.offsetWidth)/2,behavior:reduced?'instant':'smooth'})},[active,reduced]);function choose(id){setScrollMode(false);setActive(id)};let m=modules.find(m=>m.id===active);return <section className="modules-section" id="modules"><div className="container"><Reveal><SectionHead eyebrow="Five independent proposed modules" title="Five focused review workflows." body="Different questions need different evidence. Select one repeat job before deciding what to bundle."/></Reveal>{cards?<div className="module-card-grid">{modules.map(m=><Reveal as="a" href={m.route} key={m.id} className={'module-card module-'+m.id} motion={m.hero} onClick={()=>track('offer_12_selected',{offer_id:m.num})}><div className="card-shutter" aria-hidden="true">{[0,1,2,3].map(n=><i key={n}/>)}</div><div className="module-card-title"><span>{m.num}</span><Icon name={m.icon} size={24}/><Icon name="arrow-up-right"/></div><h3>{m.name}</h3><p>{m.copy}</p><Exhibit kind={m.hero} compact id={'offer-'+m.id}/><span className="text-link">Explore proposed module <Icon name="arrow-right" size={16}/></span></Reveal>)}</div>:<><div className={"module-scroll-stage "+(reduced?"static-modules":"")} ref={stage}><div className="module-scroll-frame" ref={frame}><div className="module-scroll-meta"><span><Icon name="git-compare-arrows" size={16}/>{reduced?"Manual tabs · motion reduced":"Scroll down to advance · scroll up to return"}</span><button disabled={reduced} aria-pressed={scrollMode&&!reduced} onClick={()=>setScrollMode(v=>!v)}>{scrollMode?"Pause scroll motion":"Resume scroll motion"}</button><span className="module-step-count">{m.num} / 05</span></div><div className="module-tabs" ref={tabs} role="tablist" aria-label="Proposed modules">{modules.map((x,i)=><button role="tab" id={'module-tab-'+x.id} aria-controls="module-panel" aria-selected={active===x.id} tabIndex={active===x.id?0:-1} key={x.id} onClick={()=>{choose(x.id);track('offer_12_selected',{offer_id:x.num})}} onKeyDown={e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?4:(i+(e.key==='ArrowRight'?1:4))%5;choose(modules[n].id);document.getElementById('module-tab-'+modules[n].id)?.focus()}}}><span>{x.num}</span>{x.name}</button>)}</div><div className={'module-panel module-'+m.id} role="tabpanel" id="module-panel" aria-labelledby={'module-tab-'+m.id} key={m.id}><div><span className="eyebrow">{m.label} · Proposed module</span><h3>{m.name}</h3><p>{m.copy}</p><Btn href={m.route} kind="text">Explore this module</Btn></div><Exhibit kind={m.hero} id={'module-home-'+m.id}/><ModuleMini id={m.id}/></div></div></div></>}</div></section>}
function Workflow(){return <Reveal as="section" className="workflow-section" motion="flow"><div className="container"><SectionHead eyebrow="The evidence-and-approval loop" title={<>A clear path.<br/>A deliberate stop.</>} body="Connect the source to the question. Then let the right human decide what follows."/><div className="workflow-path">{[['01','Source','files','Executed terms, dated usage and invoice evidence.','Permissioned exports'],['02','Review','git-compare-arrows','Compare the clause, quantity and line. Keep credits visible.','NOT VERIFIED'],['03','Decision','user-round','Finance confirms, dismisses or holds. Billability stays separate.','Human authority']].map(([n,t,i,p,b])=><div key={t}><div className="workflow-number"><span>{n}</span><Icon name={i}/></div><h3>{t}</h3><p>{p}</p><Badge>{b}</Badge></div>)}</div><div className="workflow-gate"><Icon name="lock-keyhole"/><span>No automatic invoicing, dunning or system writes.</span><a href="/how-it-works">Follow the complete workflow <Icon name="arrow-right" size={16}/></a></div></div></Reveal>}
function ProofStrip(){return <div className="proof-strip container"><p className="buyer-qualifier">For CFOs and billing operations leads at B2B SaaS companies with negotiated terms and usage-based charges.</p><div><Icon name="files"/><span><b>20 contract-months</b>Proposed first sample</span></div><div><Icon name="git-compare-arrows"/><span><b>One billing / CRM pair</b>Permissioned exports first</span></div><div><Icon name="user-round"/><span><b>Finance retains authority</b>Every correction is reviewed</span></div></div>}
function FAQ({limit=faq.length,title='Questions worth settling first.'}){return <section className="faq-section" id="faq"><div className="container"><div className="faq-intro"><span className="eyebrow">Before the pilot</span><h2>{title}</h2><p>Product status, scope and decisions—without the fine-print surprises.</p><a href="/contact" className="text-link">Put your question in context <Icon/></a></div><div className="faq-list">{faq.slice(0,limit).map(([q,a],i)=><details key={q} onToggle={e=>{if(e.currentTarget.open)e.currentTarget.classList.add('opened')}}><summary><span>{q}</span><Icon name="plus" size={19}/></summary><div><p>{a}</p>{i===1&&<a href="/resources/payment-failure-vs-unbilled" className="text-link">Read the workflow guide <Icon name="arrow-right" size={16}/></a>}</div></details>)}</div></div></section>}
function FlipControl({title,body,reverse,icon}){const [flipped,setFlip]=useState(false),wrap=useRef(null),pinned=useRef(false);function change(on){pinned.current=on;setFlip(on);setTimeout(()=>wrap.current?.querySelector(on?'.back button':'.control-face:not(.back) button')?.focus(),matchMedia('(prefers-reduced-motion:reduce)').matches?0:660)}return <div ref={wrap} className={'control-flip '+(flipped?'flipped':'')} onPointerEnter={e=>{if(e.pointerType==='mouse'&&!pinned.current&&!matchMedia('(prefers-reduced-motion:reduce)').matches&&!document.documentElement.classList.contains('motion-reduced')&&!wrap.current.contains(document.activeElement))setFlip(true)}} onPointerLeave={()=>{if(!pinned.current&&!wrap.current.contains(document.activeElement))setFlip(false)}}><div className="control-flip-inner"><div className="control-face" aria-hidden={flipped} inert={flipped?true:undefined}><Icon name={icon} size={28}/><h3>{title}</h3><p>{body}</p><button onClick={()=>change(true)}>Inspect the boundary <Icon name="arrow-up-right" size={16}/></button></div><div className="control-face back" aria-hidden={!flipped} inert={!flipped?true:undefined}><span className="eyebrow">Control / concept preview</span><h3>{title}</h3><p>{reverse}</p><button onClick={()=>change(false)}>Return to summary <Icon name="arrow-left" size={16}/></button></div></div></div>}
function ControlsPreview(){return <section className="controls-preview"><div className="container"><Reveal><SectionHead eyebrow="Designed around authority" title="The decision stays with finance." body="Source-linked evidence makes a proposal inspectable. It does not authorize a customer-facing correction."/></Reveal><div className="control-grid"><FlipControl title="Trace the source." icon="file-check" body="Keep the executed clause and original record in view." reverse="Document IDs, spans, dates and assumptions travel with the candidate. Evidence-quality labels do not represent calibrated accuracy."/><FlipControl title="Review the amount." icon="receipt-text" body="Gross candidates, credits and billability stay separate." reverse="The $80 candidate is unverified. CR-40 applicability is pending. A conditional $40 net still needs finance and contract/legal review."/><FlipControl title="Hold the action." icon="lock-keyhole" body="Approval is a state, not an automatic invoice or send." reverse="No back-bill is issued without contract/legal approval. No customer message is sent without approved recipient, amount and wording. All external actions are blocked here."/></div><a className="text-link" href="/controls">Explore controls and limits <Icon/></a></div></section>}
function Pricing(){const priceRef=useRef(null);useEffect(()=>{const element=document.getElementById('pricing');if(!element)return;const observer=new IntersectionObserver(es=>{if(es[0].isIntersecting){track('price_view',{intent:'pilot-pricing'});observer.disconnect()}},{threshold:.3});observer.observe(element);return()=>observer.disconnect()},[]);return <Reveal as="section" className="pricing-section" id="pricing" motion="scope"><div className="container pricing-layout"><div><span className="eyebrow">A bounded commercial hypothesis</span><h2>Prove the question<br/>before widening the scope.</h2><p>Start with contract reconciliation. Agree the sources, reviewers and criteria before a purchase decision.</p><Btn href="/evaluation" kind="text">See the evaluation criteria</Btn></div><div className="pricing-card"><div className="v-topline"><span>Proposed reconciliation pilot</span><Badge type="warning">Hypothetical price</Badge></div><div className="price">$3,000 <span>fixed pilot</span></div><p>One billing/CRM pair. Twenty contract-months.<br/>Finance-reviewed discrepancy ledger.</p><ul>{['Permissioned exports under NDA','Source spans, credit evidence and decisions','Previously unknown vs. already-known findings','Historical billability measured separately'].map(t=><li key={t}><Icon name="check" size={16}/>{t}</li>)}</ul><Btn href="/request-pilot" onClick={()=>track('price_view',{intent:'fixed-pilot'})}>Discuss a pilot</Btn><small>Ongoing single-stack test hypothesis: $2,000–$6,000 / month. Neither price is an active checkout offer or validated buyer acceptance.</small></div></div></Reveal>}
function ResourcesCards(){return <section className="resources-section" id="guides"><div className="container"><Reveal><SectionHead eyebrow="From the review library" title="Bring better questions to the table." body="Three illustrated guides for understanding the workflow, credits and a useful first sample."/></Reveal><div className="resource-grid">{resources.map(r=><Reveal as="a" className="resource-card" href={r.route} key={r.route} motion={r.visual}><div className="resource-visual"><Exhibit kind={r.visual} labels={r.visual==='bundle'?['Signed terms','Usage','Invoices','Credits']:[]} compact/></div><span className="eyebrow">{r.label} · {r.time}</span><h3>{r.title}</h3><p>{r.body}</p><span className="resource-arrow"><Icon name="arrow-up-right"/></span></Reveal>)}</div></div></section>}
function CTA({module}){return <section className="final-cta"><div className="container"><span className="eyebrow">Begin with a narrow question</span><h2>{module?'Scope '+module.name.toLowerCase()+'.':<>What do your signed terms<br/>say your invoice should contain?</>}</h2><p>A finance-reviewed sample under NDA. A clear owner.<br/>A paid pilot decision grounded in the evidence.</p><div className="row center"><Btn href={'/request-pilot'+(module?'?module='+module.id:'')}>Discuss {module?'this module':'a pilot'}</Btn><Btn href="/demo" kind="secondary" flip>Explore the example</Btn></div><small>Research-stage concept · No source-record uploads through this website</small></div></section>}
function Home(){return <><section className="home-hero" id="home-hero" tabIndex={-1}><div className="container hero-copy"><span className="eyebrow hero-eyebrow"><span/>Contract-to-invoice review</span><h1>Find contract-to-bill gaps<br className="desktop-break"/> before chasing failed payments.</h1><p>Review signed terms, usage and invoices.<br className="mobile-break"/> Keep correction decisions with finance.</p><div className="row center"><Btn href="/demo" onClick={()=>track('demo_open')}>Explore the example</Btn><Btn href="/request-pilot" kind="secondary" flip>Discuss a pilot</Btn></div><span className="stage-note"><i/>Research-stage concept · Synthetic product preview</span></div><div className="wide-container"><VideoHero/></div></section><ProofStrip/><NarrativeSection context="home" index={0} item={{title:<>A missing invoice line<br/>is a question.<br/>Evidence makes it reviewable.</>,body:'A failed payment starts with an existing charge. A contract-to-bill gap starts with an obligation that may never have reached the invoice. Locate the missing step before choosing the remedy.',visual:'fork',labels:[],layout:'split',link:'/why-earnedline',linkLabel:'Understand the distinction'}}/><NarrativeSection context="home" index={1} item={{title:'Show the line behind the number.',body:'In this fictional example, 12,000 metered events exceed an included 10,000. At $0.04 per additional event, the $80 candidate still needs finance review, credit evidence and a separate billability decision.',visual:'arithmetic',labels:[],layout:'split',link:'/demo',linkLabel:'Open the source evidence'}}/><ModuleExplorer/><Workflow/><section className="demo-preview-section"><div className="container"><Reveal><SectionHead eyebrow="Open the record" title="An exception with its context intact." body="The queue, source evidence, reviewer and next action belong in the same workbench."/></Reveal><div className="scroll-review-stage"><Workbench compact/></div><div className="demo-preview-actions"><span><Icon name="eye"/>All ten records are fictional.</span><Btn href="/demo" kind="secondary">Enter the interactive demo</Btn></div></div></section><NarrativeSection context="home" index={2} item={{title:'Fit the review around your stack.',body:'Billing-system integrators, RevOps consultants and finance-ops partners can help define a narrow export boundary. No live integrations are claimed. Start with one billing/CRM pair and compare against its existing exception reports.',visual:'mapping',labels:['Billing export','CRM export','Signed terms','Evidence ledger'],layout:'split',link:'/use-cases',linkLabel:'Explore roles and operating context'}}/><ControlsPreview/><Pricing/><ResourcesCards/><FAQ limit={8}/><CTA/></>}
function pageTargets(p){const own=modules.find(m=>m.id===p.id);if(own)return['/demo?module='+own.id,'/request-pilot?module='+own.id];const map={why:['#content','/request-pilot'],products:['#modules','/request-pilot'],how:['#content','/request-pilot'],usecases:['#content','/request-pilot'],pilot:['/request-pilot','#pricing'],controls:['#content','/legal/privacy'],evaluation:['#content','/request-pilot'],resources:['#guides','/request-pilot'],about:['#content','/contact'],contact:['#inquiry','/legal/privacy'],'guide-payments':['#content','/demo'],'guide-credits':['#content','/products/cash-bridge'],'guide-prep':['#content','/request-pilot']};return map[p.id]||['#content','/request-pilot']}
function PageHero({page}){const target=pageTargets(page),m=modules.find(m=>m.id===page.id);const kind=m?.hero||({why:'fork',products:'atlas',how:'lineage',usecases:'roles',pilot:'scope',controls:'gates',evaluation:'evaluation',resources:'reading-sequence',about:'brand',contact:'channels','guide-payments':'fork','guide-credits':'credit','guide-prep':'bundle'}[page.id]);let labels=m?[]:({products:modules.map(m=>m.name),how:['Permissioned input','Evidence ledger','Owner decision','Reviewed export'],usecases:['CFO','Billing operations','RevOps'],pilot:['1 stack','20 contract-months','NDA first'],controls:['Source','Finance','Contract/legal','Export'],evaluation:['Previously unknown','Already known','Invalid','Held'],resources:resources.map(r=>r.label),about:['Evidence','Authority','Reversibility'],contact:['Pilot scope','Walkthrough','Data handling'],'guide-prep':['Executed agreement','Dated usage','Invoice lines','Credit records']}[page.id]||[]);const wide=['products','renewals','cash','how','usecases','controls'].includes(page.id);return <section className={'page-hero hero-'+page.id+(wide?' hero-wide':'')+(page.id==='controls'?' hero-dark':'')}><div className="container"><div className="page-hero-copy"><span className="eyebrow"><a href={m?'/products':'/'}>{m?'Products':'EarnedLine'}</a><span>/</span>{m?m.name:page.route.split('/').filter(Boolean).at(-1)?.replaceAll('-',' ')||'Overview'}</span><h1>{page.title}</h1><p>{page.description}</p><div className="row"><Btn href={target[0]}>{page.primary_cta}</Btn><Btn href={target[1]} kind="secondary" flip>{page.secondary_cta}</Btn></div><small className="stage-note">{m?'Proposed module':'Research-stage concept'} · Illustrative visuals</small></div><Reveal className="page-hero-art" motion={kind}><Exhibit kind={kind} labels={labels} id={'hero-'+page.id}/></Reveal></div></section>}
function Sources(){return <div className="source-notes container"><span className="eyebrow">Public source notes</span><p>Vendor-authored sources establish capabilities and workflow overlap. They do not demonstrate demand, incremental recovery or superiority for EarnedLine.</p><div>{sourceLinks.map(([l,h])=><a href={h} target="_blank" rel="noreferrer" key={h}>{l}<Icon name="external-link" size={15}/></a>)}</div></div>}
function ProductPage({page}){const m=modules.find(x=>x.id===page.id);return <><PageHero page={page}/><div id="content" className="product-narrative" data-product={m.id}>{moduleSections(m).map((s,i)=><NarrativeSection key={i} item={s} index={i} context={m.id}/>)}</div><section className="related-modules container"><span className="eyebrow">Keep the offers distinct</span><h2>A different question needs a different module.</h2><div>{modules.filter(x=>x.id!==m.id).map(x=><a key={x.id} href={x.route}><Icon name={x.icon}/><span><b>{x.name}</b><small>{x.question}</small></span><Icon name="arrow-up-right"/></a>)}</div></section><FAQ limit={6}/><CTA module={m}/></>}
function GeneralPage({page}){const guide=page.id.startsWith('guide-');return <><PageHero page={page}/>{page.id==='products'&&<ModuleExplorer cards/>}{page.id==='resources'&&<ResourcesCards/>}<div id="content" className={guide?'guide-content':''} data-guide={guide?page.id:undefined}>{(sections[page.id]||[]).map((s,i)=><NarrativeSection key={i} item={s} index={i} context={page.id}/>)}</div>{['pilot','products'].includes(page.id)&&<Pricing/>}{['resources','why','guide-payments'].includes(page.id)&&<Sources/>}{page.id==='contact'&&<Intake intent="contact"/>}{['pilot','how','controls','why','evaluation'].includes(page.id)&&<FAQ limit={6}/>}<CTA/></>}
export function Intake({intent='pilot'}){const [state,setState]=useState('idle'),[message,setMessage]=useState(''),[selection,setSelection]=useState('contract');useEffect(()=>{const q=new URLSearchParams(location.search).get('module');if(modules.some(m=>m.id===q))setSelection(q)},[]);async function submit(e){e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const data=Object.fromEntries(new FormData(f));setState('loading');track('buyer_qualified',{role:data.role});track('pilot_request',{intent,offer_id:modules.find(m=>m.id===selection)?.num});track('consent_submit',{intent});const endpoint=import.meta.env.VITE_INTAKE_ENDPOINT;if(!endpoint){setState('preview');setMessage('Your inquiry draft is prepared. Request delivery is not connected; nothing was sent or stored.');return}try{const response=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,module:selection,intent})});if(!response.ok)throw new Error('delivery');setState('delivered');setMessage('Your inquiry was delivered. Continue to the next-step page.')}catch{setState('error');setMessage('The request was not delivered. Your input is preserved; retry when the connection is available.')}}return <section className="intake-section" id="inquiry"><div className="container intake-layout"><div className="intake-context"><span className="eyebrow">{intent==='demo'?'A guided concept walkthrough':intent==='contact'?'Start a conversation':'A bounded pilot inquiry'}</span><h2>{intent==='demo'?'See the evidence loop.':intent==='contact'?'Put the question in context.':'Bring the workflow. Scope the evidence.'}</h2><p>{intent==='demo'?'Walk through sources, credit review, overrides and approval using fictional records.':'Begin with role, company and your billing question. Agree scope, NDA and handling before providing source records.'}</p><div className="intake-steps">{['Share minimum context','Agree scope and reviewers','Arrange permissioned handling'].map((l,i)=><div key={l}><span>{i+1}</span>{l}</div>)}</div><Exhibit kind={intent==='demo'?'lineage':'bundle'} labels={intent==='demo'?['Source','Credit','Override','Approval']:['Signed terms','Usage','Invoices','Credits']} compact/><div className="intake-notice"><Icon name="lock-keyhole"/><p>No contract, invoice, financial record or customer-data uploads through this form.</p></div></div><form className="intake-form" onSubmit={submit}><div className="form-heading"><h3>{intent==='demo'?'Request a walkthrough':intent==='contact'?'Your inquiry':'Discuss a reconciliation pilot'}</h3><Badge>Concept preview</Badge></div><p className="form-disclosure">Request delivery is not connected in this preview. Only enter illustrative contact details to test the form.</p><div className="form-grid"><div className="field"><label htmlFor="field-name">Full name</label><input id="field-name" name="name" autoComplete="name" required placeholder="Your name" maxLength={100}/></div><div className="field"><label htmlFor="field-email">Work email</label><input id="field-email" name="email" type="email" autoComplete="email" required placeholder="name@company.com" maxLength={160}/></div><div className="field"><label htmlFor="field-company">Company</label><input id="field-company" name="company" autoComplete="organization" required placeholder="Company name" maxLength={120}/></div><div className="field"><label htmlFor="field-role">Role</label><select id="field-role" name="role" required defaultValue=""><option value="" disabled>Select role</option>{['CFO','Billing operations lead','RevOps leader','Revenue analyst','Integrator / consultant'].map(x=><option key={x}>{x}</option>)}</select></div><div className="field"><label htmlFor="field-billing">Billing system</label><input id="field-billing" name="billing" placeholder="Current billing system" maxLength={100}/></div><div className="field"><label htmlFor="field-crm">CRM</label><input id="field-crm" name="crm" placeholder="Current CRM" maxLength={100}/></div></div><div className="field"><label htmlFor="field-module">First proposed module</label><select id="field-module" name="module" value={selection} onChange={e=>{setSelection(e.target.value);track('offer_12_selected',{offer_id:modules.find(m=>m.id===e.target.value)?.num})}}>{modules.map(m=><option value={m.id} key={m.id}>{m.name}</option>)}</select></div>{intent==='pilot'&&<div className="field"><label htmlFor="field-sample_readiness">Sample readiness</label><select id="field-sample_readiness" name="sample_readiness" defaultValue=""><option value="">Select readiness</option><option>Can discuss a permissioned sample under NDA</option><option>Need approval from a data owner</option><option>Exploring scope first</option></select></div>}<div className="field"><label htmlFor="field-question">Your workflow question</label><textarea id="field-question" name="question" rows={3} placeholder="Describe the workflow, without customer identifiers or financial details." maxLength={600}/></div><label className="consent"><input type="checkbox" name="purpose_consent" required/><span>I agree to follow-up for this inquiry only. I have read the <a href="/legal/privacy">privacy notice</a>.</span></label><label className="consent optional"><input type="checkbox" name="marketing_consent"/><span>Separately, I would like future EarnedLine updates. Optional.</span></label><Btn className="form-submit" type="submit" disabled={state==='loading'}>{state==='loading'?'Preparing…':'Prepare inquiry draft'}</Btn><div className={'form-status '+state} role="status" aria-live="polite">{message||'Nothing is sent or stored by the preview form.'}</div>{(state==='preview'||state==='delivered')&&<a href={'/request-received?mode='+state} className="text-link">View the scoped next step <Icon/></a>}<small className="form-privacy">To discuss data handling or deletion, use the <a href="/contact">contact route</a>. Real transfer and retention terms must be agreed before a pilot.</small></form></div></section>}
function IntakePage({page}){return <><section className="intake-page-heading container"><span className="eyebrow">{page.id==='request-demo'?'The concept walkthrough':'The first review'}</span><h1>{page.title}</h1><p>{page.description}</p></section><Intake intent={page.id==='request-demo'?'demo':'pilot'}/><NarrativeSection context={page.id} index={0} item={{title:'A clear next step, before any data moves.',body:'Context first, then scope, reviewers, NDA and permissioned handling. The public preview cannot deliver a request or accept sensitive source records. It can show the exact conversation a bounded pilot needs.',visual:'nextsteps',labels:['Context','Scope','Permission','Sample'],layout:'wide'}}/><FAQ limit={4}/></>}
function DemoPage(){return <><section className="demo-page-hero container"><span className="eyebrow">The review workbench / Concept preview</span><h1>Open one discrepancy.<br/>Make a review decision.</h1><p>Trace the signed term, event total and invoice line. Keep credit applicability and historical billability separate.</p><div className="row center"><Badge>DEMO · SYNTHETIC DATA</Badge><Badge type="warning">No external actions</Badge></div></section><div className="wide-container"><Workbench/></div><div className="container demo-data-notice"><Icon name="info"/><p>All people, organizations, source documents, amounts and outcomes are fictional. Editable assumptions are a demonstration, not a legal determination or calibrated model confidence.</p><a href="/controls">Controls and limits <Icon/></a></div><NarrativeSection context="demo" index={0} item={{title:'Provenance travels with the decision.',body:'The opened record links CT-22/C-22, September usage, I-88 and CR-40. Signed and effective dates are fixed; the owner and dated next action stay visible. Reviewer reasons preserve the override context.',visual:'provenance',labels:['CT-22 / C-22','September usage','I-88','CR-40'],layout:'split'}}/><NarrativeSection context="demo" index={1} item={{title:'Review a candidate. Export an illustration.',body:'Confirmation is separate from contract/legal approval. The demo only creates a local, watermarked export after its simulated gates. Invoices, customer messages, payments and external system writes remain unavailable.',visual:'gates',labels:['Finance confirmed','Credit resolved','Contract/legal','Illustrative export'],layout:'dark'}}/><CTA/></>}
function SignIn(){const [help,setHelp]=useState(false),[status,setStatus]=useState('');return <section className="signin-page"><div className="container signin-layout"><div className="signin-art"><span className="eyebrow">The review workspace</span><h1>A clear record.<br/>A deliberate decision.</h1><p>Source evidence, human authority and a held action—together in one review.</p><Reveal motion="queue"><Exhibit kind="queue"/></Reveal><small>CONCEPT PREVIEW · Authentication is not connected.</small></div><div className="signin-panel"><img src="/brand/logos/earnedline-mark-olive.svg" width="40" height="40" alt=""/><h2>Welcome to EarnedLine.</h2><p>Workspace access is a prototype presentation. Explore the synthetic demo to try the workflow.</p><form onSubmit={e=>{e.preventDefault();setStatus('Authentication is not connected. No email or credentials were sent.')}}><div className="field"><label htmlFor="field-work-email">Work email</label><input id="field-work-email" type="email" required placeholder="name@company.com" autoComplete="off"/></div><div className="field"><label htmlFor="field-password">Password</label><input id="field-password" type="password" disabled placeholder="Authentication not connected" aria-describedby="auth-limit"/></div><div className="signin-help"><span id="auth-limit"><Icon name="lock-keyhole" size={16}/>Do not enter a password.</span><button type="button" onClick={()=>setHelp(!help)}>Need access?</button></div><Btn type="submit" kind="secondary">Preview access state</Btn><p role="status" className="form-status">{status}</p></form>{help&&<div className="access-help"><h4>Prototype access</h4><p>No account, password recovery or SSO service is connected. Request a walkthrough to discuss future access.</p><a href="/request-demo">Request a walkthrough <Icon/></a></div>}<div className="signin-divider"><span>Or try the workflow</span></div><Btn href="/demo">Enter the synthetic demo</Btn><p className="signin-legal"><a href="/legal/privacy">Privacy</a><span>·</span><a href="/legal/terms">Terms</a><span>·</span><a href="/contact">Help</a></p></div></div></section>}
const legalCopy={privacy:[['Scope of this preview','This website introduces the EarnedLine research-stage concept and an isolated synthetic workbench. Public product examples use fictional entities and records. This notice describes the implementation currently shown; operational pilot handling requires a separate agreement.'],['Inquiry context and consent','The preview intake forms validate locally. No request-delivery endpoint is configured, so entered contact information is not sent or retained by the forms. Purpose-specific consent and a separate optional updates checkbox are shown for the future connected workflow.'],['Source records','Do not enter signed contract text, customer identifiers, invoices, event feeds or financial records through public forms. Any real sample needs authority to provide records, NDA and agreed access, purpose, retention and deletion before transfer.'],['Events and local behavior','This preview creates a bounded in-memory event journal for route views, selected offer IDs, demo and evidence interactions, pricing views and form actions. It contains no raw case records, amounts, email addresses or form text and is cleared on page reload. No analytics service receives it. The selected motion preference is stored locally in your browser. Source and campaign query parameters are limited to short strings.'],['Storage and service providers','This concept website is hosted as a private preview. Browser and hosting infrastructure may process standard request information needed to serve it. No certification, regional residency, retention policy or production service assurance is claimed. Final providers and retention terms must be documented before collecting real inquiry or pilot data.'],['Deletion and questions','The local form does not retain submissions. For a future connected workflow or permissioned pilot, agree a working contact and deletion process before collection. The contact page presents the inquiry route; delivery is not connected in this preview.'],['Draft status','This is a draft implementation notice dated 13 October 2026, subject to matching the final legal entity, collection behavior, service providers and counsel-reviewed terms before an operational launch.']],terms:[['Concept-preview scope','EarnedLine is a proposed evidence-and-approval workflow. The website and synthetic demo are not an operating revenue-recovery service. All people, records, amounts and outcomes shown in the demo are fictional.'],['Permission and responsibilities','A real pilot requires an agreed scope, a permitted sample and authority to provide the relevant records. NDA and handling terms must be settled before transferring source documents. Public forms are not a channel for those documents.'],['Review authority','Finance reviewers validate discrepancies and exclusions. Contract/legal owners assess ambiguous terms and historical billability. A candidate amount, a confirmed discrepancy, an approved correction and collected cash are distinct states.'],['External actions','The preview issues no invoices, sends no customer messages, collects no payments and writes to no billing, CRM, ERP or bank system. Never send back-bills without contract/legal approval. Any future outbound message requires approval of its balance, recipient and wording.'],['Commercial hypotheses','The $3,000 fixed pilot and $2,000–$6,000 per month single-stack prices are test hypotheses. They are not current checkout offers, validated market prices or a binding commercial commitment. Any paid pilot requires a separate agreed price, scope and decision.'],['Outcomes and assurance','No recovery, ROI, compliance, certification, integration or eligibility outcome is guaranteed or established by the concept preview. Existing platforms and current analyst processes may provide equivalent exceptions. Pilot continuation depends on finance-validated incremental value and a paid commitment with licensed access.'],['Draft status','This responsibility statement is a draft dated 13 October 2026. The legal entity, jurisdiction and binding commercial terms must be supplied and reviewed by counsel before an operational service launch.']]};
function LegalPage({page}){const list=legalCopy[page.id];return <><section className="legal-hero container"><span className="eyebrow">Draft notice · 13 October 2026</span><h1>{page.title}</h1><p>{page.description}</p><Reveal motion={page.id==='privacy'?'lifecycle':'gates'}><Exhibit kind={page.id==='privacy'?'lifecycle':'gates'} labels={page.id==='privacy'?['Public context','Permissioned scope','Agreed handling','Deletion route']:['Client permission','Finance authority','Legal approval','Agreed scope']}/></Reveal></section><div className="container legal-layout"><nav aria-label="On this page"><span className="eyebrow">On this page</span>{list.map(([t],i)=><a key={t} href={'#notice-'+i}>{t}</a>)}</nav><article>{list.map(([t,b],i)=><section key={t} id={'notice-'+i}><span>{String(i+1).padStart(2,'0')}</span><h2>{t}</h2><p>{b}</p></section>)}<div className="legal-contact"><Icon name="mail"/><span>Questions about data or responsibilities?</span><a href="/contact">View contact route <Icon/></a></div></article></div></>}
function Receipt(){return <><section className="receipt-hero container"><div className="receipt-check"><Icon name="file-check" size={32}/></div><span className="eyebrow">Illustrative next step</span><h1>Your inquiry draft<br/>has a clear scope.</h1><p>The preview did not deliver a request. This page shows the preparation that would follow a connected, confirmed inquiry.</p><div className="row center"><Btn href="/resources/pilot-preparation">Review pilot preparation</Btn><Btn href="/" kind="secondary">Return home</Btn></div><Reveal motion="flow"><Exhibit kind="nextsteps" labels={['Scope discussion','Review owners','NDA + handling','Permissioned sample']}/></Reveal></section><NarrativeSection context="receipt" index={0} item={{title:'Prepare context before records.',body:'Describe the selected module, billing/CRM pair, sample readiness and finance owner. Do not upload raw documents through the website. Agree data permission, handling and deletion first.',visual:'bundle',labels:['Workflow context','Source rights','Review owners','Baseline'],layout:'split'}}/></>}
function NotFound(){return <section className="not-found container"><span className="eyebrow">404 / A disconnected line</span><h1>This line does not<br/>lead to a page.</h1><div className="broken-line"><i/><Icon name="link-2"/><i/></div><p>Find the evidence, the proposed products or a useful place to start.</p><div className="row center"><Btn href="/">Return home</Btn><Btn href="/demo" kind="secondary">Explore the example</Btn></div><div className="recovery-links"><a href="/products">Products</a><a href="/pilot">Pilot + pricing</a><a href="/contact">Contact</a></div></section>}
export function App({route='/'}){const path=route.replace(/\/$/,'')||'/';useScrollEntrances(path);const page=pages.find(p=>p.route===path)||pages.find(p=>p.id==='404');useEffect(()=>{track('landing_view',{path});if(path==='/demo')track('demo_open');const media=matchMedia('(prefers-reduced-motion:reduce)');const motion=media.matches||localStorage.getItem('earnedline-motion')==='true';document.documentElement.classList.toggle('motion-reduced',motion);window.dispatchEvent(new CustomEvent('earnedline-motion',{detail:motion}));const handler=e=>track(e.detail.name,e.detail.context);window.addEventListener('earnedline-event',handler);return()=>window.removeEventListener('earnedline-event',handler)},[path]);let body;if(page.id==='home')body=<Home/>;else if(modules.some(m=>m.id===page.id))body=<ProductPage page={page}/>;else if(page.id==='demo')body=<DemoPage/>;else if(page.id==='signin')body=<SignIn/>;else if(['request-pilot','request-demo'].includes(page.id))body=<IntakePage page={page}/>;else if(['privacy','terms'].includes(page.id))body=<LegalPage page={page}/>;else if(page.id==='404')body=<NotFound/>;else if(page.id==='success')body=<Receipt/>;else body=<GeneralPage page={page}/>;return <div data-theme={page.id==='home'?'home':'technical'} className={'app page-'+page.id}>{page.id==='home'&&<IntroVideo/>}<Header route={path}/><main id="main" tabIndex={-1}>{body}</main><Footer/></div>}
